#include "ui_styles.h"

#include "ui.h"      // screens.h: objects, ScreensEnum
#include "styles.h"  // add_style_X()/remove_style_X(), generated by EEZ
#include "ui_vars.h"

// -- Tyre fill (4-state, shared by pressure severity and slip severity) --
// EEZ's "start" style for this group is st_tyre_nodata, which is
// TYRE_SEV_NODATA == 0, so a zero-initialized cache already matches it
// (docs/ui-tyres-4wd-spec.md 6.2: "ui_styles.c must initialise its cached
// state to match [the start style]").
static void apply_tyre_fill(lv_obj_t *obj, tyre_severity_t *cached, tyre_severity_t want)
{
    if (*cached == want) {
        return;
    }
    static void (*const remove_fn[])(lv_obj_t *) = {
        remove_style_st_tyre_nodata, remove_style_st_tyre_ok, remove_style_st_tyre_caution, remove_style_st_tyre_alert,
    };
    static void (*const add_fn[])(lv_obj_t *) = {
        add_style_st_tyre_nodata, add_style_st_tyre_ok, add_style_st_tyre_caution, add_style_st_tyre_alert,
    };
    remove_fn[*cached](obj);
    add_fn[want](obj);
    *cached = want;
}

// -- Tyre highlight (add/remove only; no "off" style needed, see spec 6.2) --
static void apply_highlight(lv_obj_t *obj, bool *cached, bool want)
{
    if (*cached == want) {
        return;
    }
    if (want) {
        add_style_st_tyre_highlight(obj);
    } else {
        remove_style_st_tyre_highlight(obj);
    }
    *cached = want;
}

// -- Coupler visual state, shared by TyrePressures and WheelsAndDiff (spec 6.2) --
typedef enum { COUP_NODATA = 0, COUP_OPEN, COUP_SLIDING, COUP_CLOSED } coupler_vis_t;

static coupler_vis_t coupler_visual_state(const etc_state_t *etc)
{
    if (etc->stale || etc->coupler == 3) {
        return COUP_NODATA;
    }
    switch (etc->coupler) {
    case 0: return COUP_OPEN;
    case 1: return COUP_SLIDING;
    case 2: return COUP_CLOSED;
    default: return COUP_NODATA;
    }
}

static void apply_coupler_ring(lv_obj_t *obj, coupler_vis_t *cached, coupler_vis_t want)
{
    if (*cached == want) {
        return;
    }
    static void (*const remove_fn[])(lv_obj_t *) = {
        remove_style_st_coupler_ring_nodata, remove_style_st_coupler_ring_open,
        remove_style_st_coupler_ring_sliding, remove_style_st_coupler_ring_closed,
    };
    static void (*const add_fn[])(lv_obj_t *) = {
        add_style_st_coupler_ring_nodata, add_style_st_coupler_ring_open,
        add_style_st_coupler_ring_sliding, add_style_st_coupler_ring_closed,
    };
    remove_fn[*cached](obj);
    add_fn[want](obj);
    *cached = want;
}

// Fill only has 3 distinct styles: NODATA and OPEN both map to "off" (spec 6.2 table).
static void apply_coupler_fill(lv_obj_t *obj, int *cached, coupler_vis_t state)
{
    int want = (state == COUP_SLIDING) ? 1 : (state == COUP_CLOSED) ? 2 : 0;
    if (*cached == want) {
        return;
    }
    static void (*const remove_fn[])(lv_obj_t *) = {
        remove_style_st_coupler_fill_off, remove_style_st_coupler_fill_sliding, remove_style_st_coupler_fill_closed,
    };
    static void (*const add_fn[])(lv_obj_t *) = {
        add_style_st_coupler_fill_off, add_style_st_coupler_fill_sliding, add_style_st_coupler_fill_closed,
    };
    remove_fn[*cached](obj);
    add_fn[want](obj);
    *cached = want;
}

// Bar is on only for OPEN (spec 6.2 table).
static void apply_coupler_bar(lv_obj_t *obj, bool *cached, coupler_vis_t state)
{
    bool want = (state == COUP_OPEN);
    if (*cached == want) {
        return;
    }
    if (want) {
        remove_style_st_coupler_bar_off(obj);
        add_style_st_coupler_bar_on(obj);
    } else {
        remove_style_st_coupler_bar_on(obj);
        add_style_st_coupler_bar_off(obj);
    }
    *cached = want;
}

void ui_styles_update(void)
{
    static tyre_severity_t s_pressure_fill[TYRE_COUNT];
    static tyre_severity_t s_slip_fill[TYRE_COUNT];
    static bool             s_highlight[TYRE_COUNT];
    static coupler_vis_t    s_ring_cached[2];
    static int              s_fill_cached[2];
    static bool             s_bar_cached[2];

    lv_obj_t *const tyre_objs[TYRE_COUNT]    = { objects.tyre_fl, objects.tyre_fr, objects.tyre_rl, objects.tyre_rr };
    lv_obj_t *const wd_tyre_objs[TYRE_COUNT] = { objects.wd_tyre_fl, objects.wd_tyre_fr, objects.wd_tyre_rl, objects.wd_tyre_rr };

    for (int pos = 0; pos < TYRE_COUNT; pos++) {
        apply_tyre_fill(tyre_objs[pos], &s_pressure_fill[pos], ui_vars_tyre_pressure_severity((tyre_pos_t)pos));
        tyre_severity_t slip_sev = ui_vars_wheel_slip_severity((tyre_pos_t)pos);
        apply_tyre_fill(wd_tyre_objs[pos], &s_slip_fill[pos], slip_sev);
        apply_highlight(wd_tyre_objs[pos], &s_highlight[pos], slip_sev == TYRE_SEV_ALERT);
    }

    coupler_vis_t coup = coupler_visual_state(&ui_vars_model()->etc);
    lv_obj_t *coupler_objs[2]      = { objects.coupler, objects.wd_coupler };
    lv_obj_t *coupler_fill_objs[2] = { objects.coupler_fill, objects.wd_coupler_fill };
    lv_obj_t *coupler_bar_objs[2]  = { objects.coupler_bar, objects.wd_coupler_bar };
    for (int i = 0; i < 2; i++) {
        apply_coupler_ring(coupler_objs[i], &s_ring_cached[i], coup);
        apply_coupler_fill(coupler_fill_objs[i], &s_fill_cached[i], coup);
        apply_coupler_bar(coupler_bar_objs[i], &s_bar_cached[i], coup);
    }
}
